content:
@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,600;1,400&family=Noto+Serif+JP:wght@300;400;500;600&family=Plus+Jakarta+Sans:wght@300;400;500;600&display=swap');

:root {
  --color-bg: #FDFBF7;
  --color-surface: #FFFFFF;
  --color-surface-subtle: #F6F2EB;
  --color-surface-tint: #EFE9DE;

  --color-primary: #3E2B1E;
  --color-primary-light: #5A402D;
  --color-primary-dark: #261A12;

  --color-accent: #C27653;
  --color-accent-hover: #AE613F;
  --color-accent-soft: #F9EFE9;

  --color-gold: #B89B66;
  --color-gold-light: #DFCEAC;

  --color-text-main: #2D241E;
  --color-text-muted: #7A6F66;
  --color-text-light: #A3978E;
  --color-border: #E8E0D5;
  --color-error: #D32F2F;
  --color-error-bg: #FFF8F8;

  --font-serif: 'Cormorant Garamond', 'Noto Serif JP', serif;
  --font-sans: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;

  --shadow-sm: 0 2px 8px rgba(62, 43, 30, 0.05);
  --shadow-md: 0 8px 24px rgba(62, 43, 30, 0.08);
  --shadow-lg: 0 16px 36px rgba(62, 43, 30, 0.12);
  --shadow-modal: 0 24px 60px rgba(38, 26, 18, 0.25);

  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --radius-pill: 9999px;

  --transition-fast: 0.2s ease;
  --transition-base: 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
  --transition-smooth: 0.5s cubic-bezier(0.16, 1, 0.3, 1);
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-sans);
  background-color: var(--color-bg);
  color: var(--color-text-main);
  line-height: 1.7;
  overflow-x: hidden;
}

body.no-scroll {
  overflow: hidden;
}

/* キーボードアクセシビリティ: フォーカス表示 */
:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

button, input, textarea, select {
  font-family: inherit;
  color: inherit;
}

/* アプリケーション全体コンテナ */
.cafe-app {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  position: relative;
  background-color: var(--color-bg);
  background-image: radial-gradient(#E8E0D5 0.75px, transparent 0.75px);
  background-size: 28px 28px;
}

/* ヘッダー & ナビゲーション */
.header {
  position: sticky;
  top: 0;
  z-index: 50;
  background-color: rgba(253, 251, 247, 0.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(232, 224, 213, 0.7);
  transition: all var(--transition-base);
}

.nav-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 1.1rem 2rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.brand-logo {
  display: flex;
  flex-direction: column;
  text-decoration: none;
  color: var(--color-primary);
  font-family: var(--font-serif);
  font-size: 1.65rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  line-height: 1.1;
  transition: opacity var(--transition-fast);
}

.brand-logo:hover {
  opacity: 0.85;
}

.brand-sub {
  font-size: 0.65rem;
  font-family: var(--font-sans);
  font-weight: 400;
  letter-spacing: 0.22em;
  color: var(--color-accent);
  text-transform: uppercase;
  margin-top: 3px;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 2rem;
  list-style: none;
}

.nav-item {
  text-decoration: none;
  font-size: 0.92rem;
  font-weight: 500;
  color: var(--color-text-main);
  letter-spacing: 0.04em;
  position: relative;
  padding: 0.4rem 0;
  transition: color var(--transition-fast);
}

.nav-item::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 2px;
  background-color: var(--color-accent);
  transition: width var(--transition-base);
}

.nav-item:hover {
  color: var(--color-accent);
}

.nav-item:hover::after {
  width: 100%;
}

.nav-btn {
  padding: 0.65rem 1.4rem;
  font-size: 0.88rem;
  font-weight: 600;
  letter-spacing: 0.05em;
  border-radius: var(--radius-pill);
  cursor: pointer;
  transition: all var(--transition-base);
  border: none;
  background-color: var(--color-primary);
  color: #FFFFFF;
  box-shadow: 0 4px 12px rgba(62, 43, 30, 0.15);
}

.nav-btn:hover {
  background-color: var(--color-primary-light);
  transform: translateY(-1px);
  box-shadow: 0 6px 16px rgba(62, 43, 30, 0.22);
}

.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  font-size: 1.6rem;
  color: var(--color-primary);
  cursor: pointer;
  padding: 0.4rem;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-sm);
}

/* 共通ボタンスタイル */
.btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.6rem;
  background-color: var(--color-primary);
  color: #FFFFFF;
  padding: 0.95rem 2.2rem;
  border-radius: var(--radius-pill);
  font-size: 0.95rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  border: 1px solid var(--color-primary);
  cursor: pointer;
  text-decoration: none;
  transition: all var(--transition-base);
  box-shadow: var(--shadow-sm);
}

.btn-primary:hover {
  background-color: var(--color-primary-light);
  border-color: var(--color-primary-light);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.btn-secondary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.6rem;
  background-color: transparent;
  color: var(--color-primary);
  padding: 0.95rem 2.2rem;
  border-radius: var(--radius-pill);
  font-size: 0.95rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  border: 1.5px solid var(--color-primary);
  cursor: pointer;
  text-decoration: none;
  transition: all var(--transition-base);
}

.btn-secondary:hover {
  background-color: var(--color-primary);
  color: #FFFFFF;
  transform: translateY(-2px);
}

/* ヒーローセクション */
.hero-section {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 5rem 1.5rem;
  background: linear-gradient(180deg, rgba(253, 251, 247, 0.4) 0%, rgba(246, 242, 235, 0.8) 100%),
              radial-gradient(ellipse at 50% 20%, rgba(194, 118, 83, 0.1) 0%, transparent 60%);
  overflow: hidden;
}

.hero-content {
  max-width: 800px;
  margin: 0 auto;
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.hero-subtitle {
  font-size: 0.9rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.3em;
  color: var(--color-accent);
  margin-bottom: 1.5rem;
  position: relative;
  display: inline-block;
  padding: 0.4rem 1.2rem;
  background-color: var(--color-accent-soft);
  border-radius: var(--radius-pill);
}

.hero-title {
  font-family: var(--font-serif);
  font-size: clamp(2.4rem, 5.5vw, 4.2rem);
  font-weight: 500;
  line-height: 1.28;
  color: var(--color-primary);
  margin-bottom: 1.8rem;
  letter-spacing: 0.04em;
}

.hero-description {
  font-size: clamp(1rem, 1.8vw, 1.15rem);
  color: var(--color-text-muted);
  max-width: 620px;
  line-height: 1.9;
  margin-bottom: 2.8rem;
  font-weight: 400;
}

.hero-actions {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1.2rem;
  flex-wrap: wrap;
}

/* 共通セクション */
.section {
  padding: 7rem 1.5rem;
  position: relative;
}

.section-header {
  text-align: center;
  max-width: 700px;
  margin: 0 auto 4.5rem auto;
}

.section-sub {
  font-size: 0.85rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.25em;
  color: var(--color-accent);
  margin-bottom: 0.75rem;
  display: block;
}

.section-title {
  font-family: var(--font-serif);
  font-size: clamp(2rem, 3.8vw, 2.75rem);
  font-weight: 500;
  color: var(--color-primary);
  line-height: 1.35;
  letter-spacing: 0.03em;
}

/* コンセプトセクション */
.concept-section {
  background-color: var(--color-surface);
  border-top: 1px solid var(--color-border);
  border-bottom: 1px solid var(--color-border);
}

.concept-grid {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 2.5rem;
}

.concept-card {
  background-color: var(--color-surface-subtle);
  border-radius: var(--radius-lg);
  padding: 3rem 2.2rem;
  text-align: center;
  border: 1px solid var(--color-border);
  transition: transform var(--transition-base), box-shadow var(--transition-base);
  display: flex;
  flex-direction: column;
  align-items: center;
}

.concept-card:hover {
  transform: translateY(-6px);
  box-shadow: var(--shadow-md);
  background-color: #FFFFFF;
}

.concept-icon {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background-color: var(--color-accent-soft);
  color: var(--color-accent);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.8rem;
  margin-bottom: 1.8rem;
  transition: transform var(--transition-base);
}

.concept-card:hover .concept-icon {
  transform: scale(1.1);
  background-color: var(--color-accent);
  color: #FFFFFF;
}

.concept-card-title {
  font-family: var(--font-serif);
  font-size: 1.45rem;
  font-weight: 500;
  color: var(--color-primary);
  margin-bottom: 1rem;
  letter-spacing: 0.04em;
}

.concept-card-text {
  font-size: 0.95rem;
  color: var(--color-text-muted);
  line-height: 1.85;
}

/* メニューセクション */
.menu-section {
  background-color: var(--color-bg);
}

.menu-tabs {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 0.8rem;
  margin-bottom: 3.5rem;
}

.menu-tab {
  background-color: transparent;
  border: 1px solid var(--color-border);
  color: var(--color-text-muted);
  padding: 0.65rem 1.6rem;
  font-size: 0.92rem;
  font-weight: 500;
  border-radius: var(--radius-pill);
  cursor: pointer;
  transition: all var(--transition-fast);
}

.menu-tab:hover {
  border-color: var(--color-primary);
  color: var(--color-primary);
}

.menu-tab-active {
  background-color: var(--color-primary);
  border-color: var(--color-primary);
  color: #FFFFFF;
  box-shadow: var(--shadow-sm);
}

.menu-tab-active:hover {
  background-color: var(--color-primary-light);
  color: #FFFFFF;
}

.menu-grid {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 2.2rem;
}

.menu-card {
  background-color: var(--color-surface);
  border-radius: var(--radius-md);
  overflow: hidden;
  border: 1px solid var(--color-border);
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}

.menu-card:hover {
  transform: translateY(-5px);
  box-shadow: var(--shadow-md);
}

.menu-card-img-wrap {
  position: relative;
  width: 100%;
  padding-top: 66.66%;
  background-color: var(--color-surface-subtle);
  overflow: hidden;
}

.menu-card-img {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform var(--transition-smooth);
}

.menu-card:hover .menu-card-img {
  transform: scale(1.06);
}

.menu-card-badge {
  position: absolute;
  top: 14px;
  right: 14px;
  background-color: rgba(62, 43, 30, 0.88);
  color: #FFFFFF;
  font-size: 0.75rem;
  font-weight: 500;
  letter-spacing: 0.05em;
  padding: 0.35rem 0.8rem;
  border-radius: var(--radius-pill);
  backdrop-filter: blur(4px);
  z-index: 2;
}

.menu-card-body {
  padding: 1.6rem 1.4rem;
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}

.menu-card-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 0.75rem;
  border-bottom: 1px dashed var(--color-border);
  padding-bottom: 0.6rem;
}

.menu-card-title {
  font-family: var(--font-serif);
  font-size: 1.18rem;
  font-weight: 600;
  color: var(--color-primary);
  letter-spacing: 0.02em;
}

.menu-card-price {
  font-family: var(--font-serif);
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--color-accent);
  white-space: nowrap;
}

.menu-card-desc {
  font-size: 0.88rem;
  color: var(--color-text-muted);
  line-height: 1.7;
}

/* アクセス・店舗情報セクション */
.access-section {
  background-color: var(--color-surface);
  border-top: 1px solid var(--color-border);
}

.access-grid {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3.5rem;
  align-items: stretch;
}

.access-info-card {
  background-color: var(--color-surface-subtle);
  border-radius: var(--radius-lg);
  padding: 3rem;
  border: 1px solid var(--color-border);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.info-list {
  display: flex;
  flex-direction: column;
  gap: 1.4rem;
  margin-bottom: 2.5rem;
}

.info-item {
  display: flex;
  flex-direction: column;
  border-bottom: 1px solid var(--color-border);
  padding-bottom: 0.9rem;
}

.info-label {
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-weight: 600;
  color: var(--color-accent);
  margin-bottom: 0.3rem;
}

.info-value {
  font-size: 1.02rem;
  color: var(--color-primary);
  font-weight: 500;
}

.facility-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.6rem;
  margin-bottom: 2.2rem;
}

.facility-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  background-color: #FFFFFF;
  color: var(--color-primary);
  font-size: 0.82rem;
  font-weight: 500;
  padding: 0.45rem 1rem;
  border-radius: var(--radius-pill);
  border: 1px solid var(--color-border);
}

/* マップカード表現 */
.map-card {
  background-color: var(--color-surface-subtle);
  border-radius: var(--radius-lg);
  border: 1px solid var(--color-border);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  min-height: 440px;
  position: relative;
}

.map-visual {
  flex-grow: 1;
  width: 100%;
  min-height: 320px;
  background-color: #E6E1D8;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  background-image: 
    linear-gradient(rgba(200, 190, 175, 0.4) 1px, transparent 1px),
    linear-gradient(90deg, rgba(200, 190, 175, 0.4) 1px, transparent 1px);
  background-size: 40px 40px;
}

.map-pin-box {
  background-color: var(--color-surface);
  padding: 1.2rem 1.6rem;
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  border: 1px solid var(--color-border);
  display: flex;
  align-items: center;
  gap: 0.8rem;
  position: relative;
  z-index: 2;
  animation: mapPulse 2.5s infinite ease-in-out;
}

@keyframes mapPulse {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-6px); }
}

.map-pin-box::after {
  content: '';
  position: absolute;
  bottom: -8px;
  left: 50%;
  transform: translateX(-50%);
  border-width: 8px 8px 0;
  border-style: solid;
  border-color: var(--color-surface) transparent transparent;
}

.map-address-banner {
  padding: 1.4rem 2rem;
  background-color: var(--color-surface);
  border-top: 1px solid var(--color-border);
  font-size: 0.92rem;
  color: var(--color-text-muted);
  display: flex;
  justify-content: space-between;
  align-items: center;
}

/* フッター */
.footer {
  background-color: var(--color-primary-dark);
  color: #ECE5DC;
  padding: 5rem 1.5rem 2.5rem;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}

.footer-content {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 2.5rem;
}

.footer-brand {
  font-family: var(--font-serif);
  font-size: 2rem;
  letter-spacing: 0.08em;
  color: #FFFFFF;
}

.footer-copy {
  font-size: 0.85rem;
  color: rgba(236, 229, 220, 0.6);
  letter-spacing: 0.04em;
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  padding-top: 2rem;
  width: 100%;
}

/* 予約・問い合わせモーダル */
.modal-backdrop {
  position: fixed;
  inset: 0;
  background-color: rgba(38, 26, 18, 0.65);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1.5rem;
  overflow-y: auto;
}

.modal-container {
  background-color: var(--color-surface);
  width: 100%;
  max-width: 580px;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-modal);
  padding: 2.8rem;
  position: relative;
  border: 1px solid var(--color-border);
  animation: modalSlideUp 0.35s cubic-bezier(0.16, 1, 0.3, 1);
}

@keyframes modalSlideUp {
  from {
    opacity: 0;
    transform: translateY(24px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 2rem;
  border-bottom: 1px solid var(--color-border);
  padding-bottom: 1.2rem;
}

.modal-title {
  font-family: var(--font-serif);
  font-size: 1.7rem;
  color: var(--color-primary);
  font-weight: 500;
  letter-spacing: 0.03em;
}

.modal-close {
  background: none;
  border: none;
  font-size: 1.5rem;
  line-height: 1;
  color: var(--color-text-light);
  cursor: pointer;
  padding: 0.4rem;
  border-radius: 50%;
  transition: all var(--transition-fast);
}

.modal-close:hover {
  color: var(--color-primary);
  background-color: var(--color-surface-subtle);
}

.form-group {
  margin-bottom: 1.4rem;
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
}

.form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.2rem;
}

.form-label {
  font-size: 0.88rem;
  font-weight: 500;
  color: var(--color-primary);
}

.form-input {
  width: 100%;
  padding: 0.8rem 1rem;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  background-color: var(--color-surface-subtle);
  font-size: 0.95rem;
  color: var(--color-text-main);
  transition: border-color var(--transition-fast), background-color var(--transition-fast), box-shadow var(--transition-fast);
  outline: none;
}

.form-input:focus {
  border-color: var(--color-accent);
  background-color: #FFFFFF;
}

/* 入力エラー時のスタイル */
.form-input-error,
.form-input:user-invalid,
.form-input:invalid:not(:placeholder-shown):not(:focus) {
  border-color: var(--color-error);
  background-color: var(--color-error-bg);
}

.form-input-error:focus,
.form-input:user-invalid:focus {
  border-color: var(--color-error);
  box-shadow: 0 0 0 2px rgba(211, 47, 47, 0.2);
}

.form-error-msg {
  font-size: 0.8rem;
  color: var(--color-error);
  margin-top: 0.2rem;
  display: block;
}

textarea.form-input {
  resize: vertical;
  min-height: 90px;
}

.form-actions {
  margin-top: 2rem;
  display: flex;
  justify-content: flex-end;
  gap: 1rem;
}

.alert-success {
  background-color: #F1F8F4;
  border: 1px solid #B8E0CB;
  color: #246B46;
  padding: 1.4rem;
  border-radius: var(--radius-md);
  margin-bottom: 1.8rem;
  font-size: 0.95rem;
  display: flex;
  align-items: center;
  gap: 0.8rem;
  line-height: 1.6;
}

/* レスポンシブ対応 */
@media (max-width: 900px) {
  .access-grid {
    grid-template-columns: 1fr;
    gap: 2.5rem;
  }
}

@media (max-width: 768px) {
  .nav-links {
    display: none;
  }

  .nav-links.nav-mobile-open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    background-color: var(--color-surface);
    padding: 1.8rem;
    box-shadow: var(--shadow-lg);
    border-bottom: 1px solid var(--color-border);
    gap: 1.4rem;
    align-items: flex-start;
  }

  .mobile-menu-btn {
    display: flex;
  }

  .section {
    padding: 5rem 1.25rem;
  }

  .hero-section {
    min-height: 75vh;
    padding: 4rem 1.25rem;
  }

  .form-row {
    grid-template-columns: 1fr;
    gap: 0;
  }

  .access-info-card {
    padding: 2rem 1.5rem;
  }

  .modal-container {
    padding: 2rem 1.5rem;
  }
}

@media (max-width: 480px) {
  .hero-actions {
    flex-direction: column;
    width: 100%;
  }

  .hero-actions .btn-primary,
  .hero-actions .btn-secondary {
    width: 100%;
  }

  .concept-card {
    padding: 2.2rem 1.5rem;
  }
}

export type MenuCategory = 'coffee' | 'tea' | 'dessert' | 'food';

export interface MenuItem {
  id: string;
  name: string;
  category: MenuCategory;
  price: number;
  description: string;
  tag?: string;
  imageUrl: string;
  allergyInfo?: string;
}

export interface StoreInfo {
  name: string;
  address: string;
  station: string;
  tel: string;
  openHours: string;
  holiday: string;
  seats: string;
  wifi: boolean;
  outlet: boolean;
  googleMapUrl?: string;
  instagramUrl?: string;
}

export interface ReservationFormValues {
  name: string;
  email: string;
  date: string;
  time: string;
  guests: number;
  requestNote: string;
}

export interface FormErrors {
  name?: string;
  email?: string;
  date?: string;
  time?: string;
  guests?: string;
  general?: string;
}

import { useState } from 'react';
import { MenuItem } from '../types';
import { MENU_ITEMS } from '../data';

type CategoryFilter = 'all' | 'coffee' | 'tea' | 'dessert' | 'food';

interface CategoryTab {
  key: CategoryFilter;
  label: string;
}

const CATEGORY_TABS: CategoryTab[] = [
  { key: 'all', label: 'すべて' },
  { key: 'coffee', label: '珈琲' },
  { key: 'tea', label: '紅茶・ティー' },
  { key: 'dessert', label: 'スイーツ' },
  { key: 'food', label: '軽食・お食事' },
];

const formatPrice = (price: number): string => {
  return `¥${price.toLocaleString()}`;
};

const MenuSection = () => {
  const [activeCategory, setActiveCategory] = useState<CategoryFilter>('all');

  const filteredItems: MenuItem[] = activeCategory === 'all'
    ? MENU_ITEMS
    : MENU_ITEMS.filter((item) => item.category === activeCategory);

  return (
    <section className="section menu-section" id="menu">
      <div className="section-header">
        <span className="section-sub">Seasonal & Classic</span>
        <h2 className="section-title">自慢のメニュー</h2>
      </div>

      <div className="menu-tabs" role="tablist" aria-label="メニューカテゴリ">
        {CATEGORY_TABS.map((tab) => {
          const isSelected = activeCategory === tab.key;
          const tabClass = isSelected ? 'menu-tab menu-tab-active' : 'menu-tab';
          return (
            <button
              key={tab.key}
              type="button"
              role="tab"
              aria-selected={isSelected}
              className={tabClass}
              onClick={() => setActiveCategory(tab.key)}
            >
              {tab.label}
            </button>
          );
        })}
      </div>

      {filteredItems.length === 0 ? (
        <div className="menu-empty" style={{ textAlign: 'center', padding: '3rem 1rem', color: 'var(--color-text-muted)' }}>
          <p>該当するメニューが見つかりませんでした。</p>
        </div>
      ) : (
        <div className="menu-grid">
          {filteredItems.map((item) => (
            <article key={item.id} className="menu-card">
              <div className="menu-card-img-wrap">
                <img
                  src={item.imageUrl}
                  alt={item.name}
                  className="menu-card-img"
                  loading="lazy"
                />
                {item.tag && (
                  <span className="menu-card-badge">{item.tag}</span>
                )}
              </div>
              <div className="menu-card-body">
                <div className="menu-card-header">
                  <h3 className="menu-card-title">{item.name}</h3>
                  <span className="menu-card-price">{formatPrice(item.price)}</span>
                </div>
                <p className="menu-card-desc">{item.description}</p>
              </div>
            </article>
          ))}
        </div>
      )}
    </section>
  );
};

export default MenuSection;

