import { useState, useEffect, useCallback, ChangeEvent, FormEvent } from 'react';
import MenuSection from './components/MenuSection';
import AccessSection from './components/AccessSection';
import { ReservationFormValues } from './types';

const INITIAL_FORM_VALUES: ReservationFormValues = {
  name: '',
  email: '',
  date: '',
  time: '14:00',
  guests: 2,
  requestNote: '',
};

const CONCEPTS = [
  {
    icon: '☕',
    title: '自家焙煎の深み',
    description: '世界各地の良質な豆を毎朝丁寧に少量ずつロースト。豆が持つ本来の芳醇なアロマと心地よい余韻を最大限に引き出します。',
  },
  {
    icon: '🪴',
    title: '陽光と静寂の空間',
    description: '店名「Lumière（光）」が示すように、天窓から降り注ぐやわらかな自然光と緑に囲まれた、心がほどける落ち着いた空間です。',
  },
  {
    icon: '🥐',
    title: '手作りの焼き菓子',
    description: '北海道産バターと契約農家の平飼い卵を使用。素材本来の風味を生かし、ひとつひとつパティシエが毎朝焼き上げています。',
  },
];

const App = () => {
  const [isModalOpen, setIsModalOpen] = useState<boolean>(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState<boolean>(false);
  const [formValues, setFormValues] = useState<ReservationFormValues>(INITIAL_FORM_VALUES);
  const [isSubmitted, setIsSubmitted] = useState<boolean>(false);

  const todayDateString = new Date().toISOString().split('T')[0];

  const handleOpenModal = () => {
    setIsSubmitted(false);
    setIsModalOpen(true);
  };

  const handleCloseModal = useCallback(() => {
    setIsModalOpen(false);
  }, []);

  const toggleMobileMenu = () => {
    setIsMobileMenuOpen((prev) => !prev);
  };

  // モーダルオープン時の Escape キー検知によるクローズ処理
  useEffect(() => {
    if (!isModalOpen) return;

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        handleCloseModal();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [isModalOpen, handleCloseModal]);

  // モーダルまたはモバイルメニューオープン時の背景スクロール防止
  useEffect(() => {
    if (isModalOpen || isMobileMenuOpen) {
      document.body.classList.add('no-scroll');
    } else {
      document.body.classList.remove('no-scroll');
    }

    return () => {
      document.body.classList.remove('no-scroll');
    };
  }, [isModalOpen, isMobileMenuOpen]);

  const handleInputChange = (
    e: ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>
  ) => {
    const { name, value } = e.target;
    setFormValues((prev) => ({
      ...prev,
      [name]: name === 'guests' ? Number(value) : value,
    }));
  };

  const handleSubmitReservation = (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setIsSubmitted(true);
  };

  return (
    <div className="cafe-app">
      {/* ヘッダーナビゲーション */}
      <header className="header">
        <div className="nav-container">
          <a href="#" className="brand-logo">
            <span>Café Lumière</span>
            <span className="brand-sub">Roastery & Coffee Stand</span>
          </a>

          <nav>
            <ul className={isMobileMenuOpen ? 'nav-links nav-mobile-open' : 'nav-links'}>
              <li>
                <a
                  href="#concept"
                  className="nav-item"
                  onClick={() => setIsMobileMenuOpen(false)}
                >
                  コンセプト
                </a>
              </li>
              <li>
                <a
                  href="#menu"
                  className="nav-item"
                  onClick={() => setIsMobileMenuOpen(false)}
                >
                  メニュー
                </a>
              </li>
              <li>
                <a
                  href="#access"
                  className="nav-item"
                  onClick={() => setIsMobileMenuOpen(false)}
                >
                  アクセス・店舗情報
                </a>
              </li>
              <li>
                <button
                  type="button"
                  className="nav-btn"
                  onClick={() => {
                    setIsMobileMenuOpen(false);
                    handleOpenModal();
                  }}
                >
                  ご予約・お問合せ
                </button>
              </li>
            </ul>
          </nav>

          <button
            type="button"
            className="mobile-menu-btn"
            aria-label="メニュー開閉"
            onClick={toggleMobileMenu}
          >
            {isMobileMenuOpen ? '✕' : '☰'}
          </button>
        </div>
      </header>

      {/* ヒーローセクション */}
      <section className="hero-section">
        <div className="hero-content">
          <span className="hero-subtitle">Specialty Coffee & Slow Life</span>
          <h1 className="hero-title">
            陽光と珈琲の香りに、<br />
            やさしく満たされる時間。
          </h1>
          <p className="hero-description">
            表参道の喧騒から一本小道を入った先に佇む、穏やかな光が射し込む隠れ家カフェ。
            選び抜かれた自家焙煎珈琲と手作りのクラシックデザートで、日常を特別なひとときへ。
          </p>
          <div className="hero-actions">
            <a href="#menu" className="btn-primary">
              メニューを見る
            </a>
            <button
              type="button"
              className="btn-secondary"
              onClick={handleOpenModal}
            >
              席を予約する
            </button>
          </div>
        </div>
      </section>

      {/* コンセプトセクション */}
      <section className="section concept-section" id="concept">
        <div className="section-header">
          <span className="section-sub">Our Philosophy</span>
          <h2 className="section-title">リュミエールのこだわり</h2>
        </div>

        <div className="concept-grid">
          {CONCEPTS.map((concept, idx) => (
            <div key={idx} className="concept-card">
              <div className="concept-icon">{concept.icon}</div>
              <h3 className="concept-card-title">{concept.title}</h3>
              <p className="concept-card-text">{concept.description}</p>
            </div>
          ))}
        </div>
      </section>

      {/* メニューセクション */}
      <MenuSection />

      {/* アクセスセクション */}
      <AccessSection onOpenReservationModal={handleOpenModal} />

      {/* フッター */}
      <footer className="footer">
        <div className="footer-content">
          <div className="footer-brand">Café Lumière</div>
          <p style={{ maxWidth: '600px', fontSize: '0.92rem', color: '#BBAE9F', lineHeight: 1.8 }}>
            静寂とあたたかな陽光に包まれた、日常をリセットできる場所。<br />
            一杯の珈琲から生まれる特別なひとときを、心を込めてお届けいたします。
          </p>
          <p className="footer-copy">
            © {new Date().getFullYear()} Café Lumière. All rights reserved.
          </p>
        </div>
      </footer>

      {/* 席のWeb予約・問い合わせモーダル */}
      {isModalOpen && (
        <div
          className="modal-backdrop"
          onClick={(e) => {
            if (e.target === e.currentTarget) {
              handleCloseModal();
            }
          }}
        >
          <div className="modal-container" role="dialog" aria-modal="true">
            <div className="modal-header">
              <h3 className="modal-title">お席のご予約・お問い合わせ</h3>
              <button
                type="button"
                className="modal-close"
                onClick={handleCloseModal}
                aria-label="閉じる"
              >
                ✕
              </button>
            </div>

            {isSubmitted ? (
              <div>
                <div className="alert-success">
                  <span style={{ fontSize: '1.4rem' }}>✓</span>
                  <div>
                    <strong>ご予約リクエストを送信しました</strong>
                    <p style={{ marginTop: '4px', fontSize: '0.88rem' }}>
                      ご入力いただいたメールアドレス（{formValues.email}）宛てに、確認メールをお送りいたしました。ご来店を心よりお待ちしております。
                    </p>
                  </div>
                </div>
                <div className="form-actions">
                  <button
                    type="button"
                    className="btn-primary"
                    onClick={handleCloseModal}
                  >
                    閉じる
                  </button>
                </div>
              </div>
            ) : (
              <form onSubmit={handleSubmitReservation}>
                <div className="form-row">
                  <div className="form-group">
                    <label className="form-label" htmlFor="name">
                      お名前 *
                    </label>
                    <input
                      type="text"
                      id="name"
                      name="name"
                      required
                      placeholder="山田 太郎"
                      className="form-input"
                      value={formValues.name}
                      onChange={handleInputChange}
                    />
                  </div>
                  <div className="form-group">
                    <label className="form-label" htmlFor="email">
                      メールアドレス *
                    </label>
                    <input
                      type="email"
                      id="email"
                      name="email"
                      required
                      placeholder="lumiere@example.com"
                      className="form-input"
                      value={formValues.email}
                      onChange={handleInputChange}
                    />
                  </div>
                </div>

                <div className="form-row">
                  <div className="form-group">
                    <label className="form-label" htmlFor="date">
                      ご来店日 *
                    </label>
                    <input
                      type="date"
                      id="date"
                      name="date"
                      min={todayDateString}
                      required
                      className="form-input"
                      value={formValues.date}
                      onChange={handleInputChange}
                    />
                  </div>
                  <div className="form-group">
                    <label className="form-label" htmlFor="time">
                      ご来店時間 *
                    </label>
                    <select
                      id="time"
                      name="time"
                      className="form-input"
                      value={formValues.time}
                      onChange={handleInputChange}
                    >
                      <option value="09:00">09:00 (モーニング)</option>
                      <option value="10:00">10:00 (モーニング)</option>
                      <option value="11:30">11:30 (ランチ)</option>
                      <option value="13:00">13:00 (ランチ)</option>
                      <option value="14:30">14:30 (カフェ)</option>
                      <option value="16:00">16:00 (カフェ)</option>
                      <option value="18:00">18:00 (ディナー)</option>
                    </select>
                  </div>
                </div>

                <div className="form-group">
                  <label className="form-label" htmlFor="guests">
                    ご利用人数 *
                  </label>
                  <select
                    id="guests"
                    name="guests"
                    className="form-input"
                    value={formValues.guests}
                    onChange={handleInputChange}
                  >
                    <option value={1}>1名様（カウンター/テーブル）</option>
                    <option value={2}>2名様（テーブル席）</option>
                    <option value={3}>3名様（テーブル席）</option>
                    <option value={4}>4名様（ソファー席）</option>
                    <option value={5}>5名様以上（お電話にてご相談）</option>
                  </select>
                </div>

                <div className="form-group">
                  <label className="form-label" htmlFor="requestNote">
                    ご要望・アレルギー等（任意）
                  </label>
                  <textarea
                    id="requestNote"
                    name="requestNote"
                    rows={3}
                    placeholder="テラス席希望、誕生日のお祝いプレート等があればご記入ください"
                    className="form-input"
                    value={formValues.requestNote}
                    onChange={handleInputChange}
                  />
                </div>

                <div className="form-actions">
                  <button
                    type="button"
                    className="btn-secondary"
                    onClick={handleCloseModal}
                  >
                    キャンセル
                  </button>
                  <button type="submit" className="btn-primary">
                    予約リクエストを送信
                  </button>
                </div>
              </form>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default App;
